    private static void initSlitherBlocks() {
        java.util.List<String> slabIds = new java.util.ArrayList<>();
        for (Identifier id : Registries.BLOCK.getIds()) {
            if (!Erydon.MOD_ID.equals(id.getNamespace())) {
                continue;
            }

            String path = id.getPath();
            if (path.startsWith("glazing_") || path.startsWith("cover_") || path.contains("_diaphanes")) {
                continue;
            }
            if (path.endsWith("_slab") || path.endsWith("_slab_aged")) {
                slabIds.add(path);
            }
        }

        java.util.Collections.sort(slabIds);
        for (String slabId : slabIds) {
            Block source = Registries.BLOCK.get(new Identifier(Erydon.MOD_ID, slabId));
            registerBlock(toSlitherId(slabId, "slice_vertical"),
                    new VerticalSliceBlock(AbstractBlock.Settings.copy(source).nonOpaque()));
            registerBlock(toSlitherId(slabId, "slice_horizontal"),
                    new HorizontalSliceBlock(AbstractBlock.Settings.copy(source).nonOpaque()));
            registerBlock(toSlitherId(slabId, "post"),
                    new PostBlock(AbstractBlock.Settings.copy(source).nonOpaque()));
        }
    }

    private static String toSlitherId(String slabId, String variant) {
        return ErydonIdMigration.canonicalSlitherPath(slabId, variant);
    }

    private static Block createWallLight() {
        return new WallLightBlock(AbstractBlock.Settings.copy(AGANITE_BLOCK).nonOpaque().luminance(LightBlock::luminance));
    }

    private static void registerGeorgianWalls() {
        for (String material : GEORGIAN_WALL_MATERIALS) {
            registerBlock(material + "_wall_georgian", createGeorgianWall());
            registerBlock(material + "_wall_georgian_aged", createGeorgianWall());
            registerBlock(material + "_ashlar_wall_georgian", createGeorgianWall());
        }

        for (String material : GEORGIAN_WALL_HERRINGBONE_MATERIALS) {
            registerBlock(material + "_herringbone_bronze_wall_georgian", createGeorgianWall());
            registerBlock(material + "_herringbone_grout_wall_georgian", createGeorgianWall());
        }

        for (String prefix : GEORGIAN_WALL_WEAVE_PREFIXES) {
            registerBlock(prefix + "_weave_bronze_wall_georgian", createGeorgianWall());
            registerBlock(prefix + "_weave_grout_wall_georgian", createGeorgianWall());
        }
    }

    private static Block createGeorgianWall() {
        return new DiagonalWallBlock(AbstractBlock.Settings.copy(AGANITE_BLOCK));
    }

