    private static void registerAlcoves(String style) {
        int maxClusterWidth = 3;
        for (String material : ARCH_MODERN_MATERIALS) {
            registerAlcove(material + "_alcove_" + style, material + "_block", maxClusterWidth);
            registerAlcove(material + "_aged_alcove_" + style, material + "_block_aged", maxClusterWidth);
            registerAlcove(material + "_ashlar_alcove_" + style, material + "_ashlar_block", maxClusterWidth);
            registerAlcove(material + "_rusticated_alcove_" + style, material + "_rusticated_block", maxClusterWidth);
            registerAlcove(material + "_hewn_alcove_" + style, material + "_hewn_block", maxClusterWidth);
            registerAlcove(material + "_rock_alcove_" + style, material + "_rock_block", maxClusterWidth);
        }
    }

