    private static Block sourceBlock(String name) {
        Identifier id = new Identifier(Erydon.MOD_ID, ErydonIdMigration.canonicalPath(name));
        Block block = Registries.BLOCK.get(id);
        if (block == Blocks.AIR) {
            throw new IllegalStateException("Missing source block: " + id);
        }
        return block;
    }

