        initLatmionHerringboneGrout();
        initPsamatheon();
        initPsamatheonHerringboneGrout();
        initLaurentium();
        initMielonyx();
        initNerium();
        initNoxoplis();
        initPortorium();
        initRosinium();
        initSanguenite();
        initSelenephos();
        initSolistra();
        initStriatus();
        registerModernArches();
        registerGothicArches();
        registerAlcoves("georgian");
        registerAlcoves("gothic");
        registerGothicCornices();
        registerGothicColumns();
        registerGeorgianWalls();

        AGANITE_BRAZIER = registerBlock("aganite_brazier", createBrazier());
        BOREALIS_BRAZIER = registerBlock("borealis_brazier", createBrazier());
        BRECTITE_BRAZIER = registerBlock("brectite_brazier", createBrazier());
        CALACATTUM_BRAZIER = registerBlock("calacattum_brazier", createBrazier());
        CHALSTROM_BRAZIER = registerBlock("chalstrom_brazier", createBrazier());
        CHRYSONYX_BRAZIER = registerBlock("chrysonyx_brazier", createBrazier());
        ETRUSCUS_BRAZIER = registerBlock("etruscus_brazier", createBrazier());
        GELASTRUM_BRAZIER = registerBlock("gelastrum_brazier", createBrazier());
        GLACIUM_BRAZIER = registerBlock("glacium_brazier", createBrazier());
        HESPERION_BRAZIER = registerBlock("hesperion_brazier", createBrazier());
        IMPERIUM_BRAZIER = registerBlock("imperium_brazier", createBrazier());
        KYLORION_BRAZIER = registerBlock("kylorion_brazier", createBrazier());
        LAURENTIUM_BRAZIER = registerBlock("laurentium_brazier", createBrazier());
        MIELONYX_BRAZIER = registerBlock("mielonyx_brazier", createBrazier());
